classdef SignalsOutputOptoSGLXExternal < hw.SignalsOutput
  %HW.SignalsOutputArduinoGeneric 
  %
  % See also HW.SignalsOutput
  %
  % Part of Rigbox
  % 2020-11 NS
  
  properties
    devID = 'Dev3';
    s = []; % daq session
    rate = 100000; 
    sglx_ip = '128.95.53.23'
    sglx_con = [];
  end
  
  
  methods
    function obj = SignalsOutputOptoSGLXExternal(name,devID)
      
        obj.Name = name;        
        obj.devID = devID;
        obj.sglx_con = 0;
        
    end

    function init(obj)
        newS = daq.createSession('ni');
        newS.addAnalogOutputChannel(obj.devID, 'ao3', 'Voltage');
        newS.addAnalogOutputChannel(obj.devID, 'ao0', 'Voltage');
        newS.addAnalogOutputChannel(obj.devID, 'ao1', 'Voltage');
        newS.addAnalogOutputChannel(obj.devID, 'ao2', 'Voltage');

        newS.Rate = obj.rate;
 
        obj.s = newS;
%         if obj.isPortOpen
%             try
%                 obj.sglx_con = SpikeGL(obj.sglx_ip,4142);
%             catch
%                 disp ('WARNING: SpikeGLX connection failed!!!! This shouldnt happen')
%             end
%         else
%             disp ('WARNING: SpikeGLX connection not attempted')
%         end
        try
            obj.sglx_con = SpikeGL(obj.sglx_ip,4142);
        catch
            disp ('WARNING: SpikeGLX connection failed!!!! This shouldnt happen')
        end
    end
    
    function command(obj, v)
        s = obj.s;
        rate = obj.rate;
        
        % extract the specified parameters
        laserAmp = v(1);
        laserDurS = v(2);
        laserDelay = v(3); 
        galvoXPos = v(4); 
        galvoYPos = v(5); 
        laserFreq = v(6); % sine wave freq
        eSite = v(7);
        extLaserAmp = v(8);
        extLaserDur = v(9);
        extLaserDelay = v(10);
        
        % Add new optional parameters
        if length(v) >= 11
            n_pulses = v(11);
            fprintf('n pulses: %i\n', n_pulses);

        else
            n_pulses = 1;
            
        end
        
        if length(v) >= 12
            ramp_rate = v(12);
        else
            ramp_rate = 0;
        end

        try
            Opto_emit(obj.sglx_con, 0, 1, -1);
%             status = Opto_emit(obj.sglx_con, 0, 1, eSite);    % blue=0, red=1
            Opto_emit(obj.sglx_con, 0, 1, eSite); 
        catch
            disp('WARNING: SpikeGLX connection failed')
        end
        
        fprintf(1, 'Opto Laser on %2.1fV %3.2fS. emission site: %4.3f\n', ...
            laserAmp, laserDurS, eSite); 
        fprintf(1, '\n ext Laser on %2.1fV %3.2fS\n', ...
            extLaserAmp, extLaserDur); 
        
        % Update timing parameters for multiple pulses
        trialTimeS = n_pulses * (laserDelay + laserDurS) + 0.001;

        % convert into NI samples
        trialTimeSamps = round(trialTimeS * rate);

        % create the waveforms for each component
        laser = obj.genLaser(laserAmp, laserDurS, laserDelay, n_pulses, ramp_rate, laserFreq);
        extLaser = obj.genLaser(extLaserAmp, extLaserDur, extLaserDelay, n_pulses, ramp_rate, laserFreq);
        galvoX = obj.genGalvo(galvoXPos, trialTimeSamps);
        galvoY = obj.genGalvo(galvoYPos, trialTimeSamps);
        
        s.queueOutputData([laser, extLaser, galvoX, galvoY]);
        s.startForeground();
    end
  
   
    
    function delete(obj)
        s = obj.s; 
        s.stop(); 
        clear s; 
    end
    
    function isOpen = isPortOpen(obj)
        ipAddress = '128.95.53.23';
        port = '4142';
        import java.net.*;
        % Create a socket
        sock = Socket();

        % Set timeout
        sock.setSoTimeout(100); % 100 ms timeout

        % Try to connect with timeout
        try
            sock.connect(InetSocketAddress(ipAddress, port), 10); % 100 ms timeout
            isOpen = 1;
            sock.close();
        catch
            isOpen = 0;
            end
    end
    
function waveform = genLaser(obj, laserAmp, laserDur, laserDelay, n_pulses, ramp_rate, laserFreq)
    rate = obj.rate;
    laserDurSamps = round(laserDur * rate);
    delayTimeSamps = round(laserDelay * rate);
    totalDuration =  n_pulses * (laserDelay + laserDur) + 0.001;
    totalSamps = round(totalDuration * rate);
    
    waveform = zeros(totalSamps, 1);
    
    for i = 1:n_pulses
        startIdx = i * (laserDurSamps + delayTimeSamps) - laserDurSamps + 1;
        endIdx = startIdx + laserDurSamps - 1;
        %build pulse template
        pulse = laserAmp * ones(laserDurSamps, 1);
        
        if ramp_rate > 0
            rampSamps = round(laserDurSamps * ramp_rate);
            % Create a scaling factor for the ramp-up and ramp-down portions
            scaleFactor = ones(laserDurSamps, 1);
            % Ramp up
            scaleFactor(1:rampSamps) = linspace(0, 1, rampSamps);
            % Ramp down
            scaleFactor(end-rampSamps+1:end) = linspace(1, 0, rampSamps);
            % Apply scaling factor to the pulse
            pulse = pulse .* scaleFactor;
        end
        
        if laserFreq ~= 0
            t = (0:laserDurSamps-1)' / rate;
            pulse = pulse .* (1 + sin(2*pi*laserFreq*t)) / 2;
        end
        
        waveform(startIdx:endIdx) = pulse;
    end
end
    
    
