    function [ramp, t] = genRamp(obj, duration, amp)
        rate = obj.rate; 
        t = 0:1/rate:duration;
        f = 1/(duration*2);
        ramp = amp*0.5*(1-cos(t*(2*pi*f))); 
    end
   
